"""Brand assets and menu presentation; does not alter order calculations."""
from pathlib import Path
from urllib.parse import unquote
import mimetypes

ROOT=Path(__file__).resolve().parent
ASSETS=ROOT/'assets'

def initialize(db):
    db.execute('CREATE TABLE IF NOT EXISTS product_presentation(product_id INTEGER PRIMARY KEY REFERENCES products(id), image TEXT NOT NULL, description TEXT NOT NULL, featured INTEGER NOT NULL DEFAULT 0)')

def brand(name='JUPITER'):
    from html import escape
    return f'<span class="brand-lockup"><img src="/assets/jupiter-mark.svg" alt="" width="48" height="48"><span class="brand-words"><b>{escape(name)}</b><small>BAR &amp; KITCHEN</small></span></span>'

def serve(handler,path):
    if not path.startswith('/assets/'): return False
    filename=unquote(path[len('/assets/'):])
    target=(ASSETS/filename).resolve()
    if not target.is_relative_to(ASSETS.resolve()) or not target.is_file() or target.suffix.lower() not in ['.svg','.webp','.png','.jpg','.css']:
        handler.respond('Not found',404); return True
    image_types={'.webp':'image/webp','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.svg':'image/svg+xml'}
    handler.respond(target.read_bytes(),content=image_types.get(target.suffix.lower()) or mimetypes.guess_type(target.name)[0] or 'application/octet-stream')
    return True

